import{_ as e,o as n,c as o,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Apuntado y evaluación","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/targeting.md","filePath":"es/game-design/combat/targeting.md"}'),t={name:"es/game-design/combat/targeting.md"};function r(s,a,d,c,l,p){return n(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="targeting-and-assessment" tabindex="-1">Apuntado y evaluación <a class="header-anchor" href="#targeting-and-assessment" aria-label="Enlace permanente a &quot;Apuntado y evaluación&quot;">​</a></h1><p><strong>Estado del diseño: Aceptado para la dirección y la política experimental de resolución. Implementación: resolución natural de Stage 2A integrada; la resolución apuntada sigue siendo pura y no se almacena intención del jugador.</strong></p><p>Un jugador puede preferir una región corporal mientras continúa el combate automático. El servidor sigue decidiendo si se produce un golpe, si acierta y dónde impacta. Seleccionar no encola un ataque extra, pausa el combate, reinicia la recuperación ni garantiza una región.</p><h3 id="accepted-experimental-first-resolver" tabindex="-1">Primera resolución experimental con estado Aceptado <a class="header-anchor" href="#accepted-experimental-first-resolver" aria-label="Enlace permanente a &quot;Primera resolución experimental con estado Aceptado&quot;">​</a></h3><p>La política aprobada para una integración posterior del impacto da a un apuntado válido una probabilidad <strong>provisional del 50%</strong> de elegir la región deseada. Si falla, se sortea cobertura natural <strong>excluyendo toda la región deseada</strong>. Una alternativa sin restricciones elevaría el éxito a <code>p + (1-p) × naturalWeight</code>, por lo que no es el prototipo especificado. El caso natural/sin intención no usa tirada de apuntado. El contacto apuntado en un brazo elige Hands:Arms con proporción 1:2.</p><p>Revalidar al defensor efectivo después de una redirección. La ausencia de armadura no vuelve a sortear ubicación. La intención puede sobrevivir a un fallo o una pérdida breve de alcance cuerpo a cuerpo, pero los cambios de Combatant/sesión/mapa/ciclo de vida invalidan el contexto. Una respuesta obsoleta no debe borrar una selección válida más reciente.</p><p>Se prevé que la evaluación use gumps existentes e instantáneas explícitas en Slice 0. Stage 2A ya proporciona la <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">vía cualitativa aprobada de Anatomy</a>; los atajos nativos siguen siendo trabajo separado. <strong>Carencia:</strong> no se ha implementado ningún servicio de selección, manejo de revisiones ni apuntado en vivo. Las comprobaciones de resolución no establecen apuntado en vivo ni validación de juego.</p><h2 id="proposed-targeting-factors-and-knowledge" tabindex="-1">Factores de apuntado y conocimiento con estado Propuesto <a class="header-anchor" href="#proposed-targeting-factors-and-knowledge" aria-label="Enlace permanente a &quot;Factores de apuntado y conocimiento con estado Propuesto&quot;">​</a></h2><p>Batch 03 conserva el apuntado como intención, nunca como bloqueo permanente garantizado de una región. Oportunidades, posición, ejecución del ataque, arma, habilidad del personaje, movimiento/defensa del defensor, información disponible y stamina/fatiga son influencias candidatas. Sus relaciones definitivas de precisión/coste siguen Sin resolver; no sustituyen la resolución experimental aceptada anterior.</p><p>Anatomy puede apoyar una selección informada del objetivo mediante conocimiento del estado corporal. La <a href="/Syrolands-Public/es/game-design/skills-and-knowledge.html">información con estado Aceptado</a> sigue siendo el límite: la propuesta no concede nueva información numérica oculta. Tactics y Arms Lore aportan funciones distintas de oportunidades/equipo. <a href="/Syrolands-Public/es/game-design/combat/stamina-and-reactive-combat.html">Stamina y entrada reactiva</a> registra el conflicto de entrada manual sin resolver sin cambiar ataques programados.</p><p><a href="/Syrolands-Public/es/guide/combat/targeting-and-anatomy.html">Guía del jugador: Ataques dirigidos y Anatomy</a>.</p>',11)])])}const g=e(t,[["render",r]]);export{m as __pageData,g as default};
